// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 ticketCount) public {
        ticketCount = bound(ticketCount, 1, 100);
        address player = makeAddr("player");
        vm.deal(player, ticketCount * 10 ether);

        uint256 lastPot;
        bool potWasNonZeroAtLeastOnce = false;

        for (uint i = 0; i < ticketCount; i++) {
            vm.prank(player);
            c.play{value: 10}();
            lastPot = c.pot();
            if (lastPot > 0) {
                potWasNonZeroAtLeastOnce = true;
            }
        }

        assertTrue(potWasNonZeroAtLeastOnce);
    }
}
